// Pick up rows a human typed into the Leads tab and marked as ready to run.
//
// TWO filters, and both matter:
//   source_config === 'manual' — the marker for a row a HUMAN typed.
//
//     Not 'demo'. The live sheet has a data-validation dropdown on this column offering exactly
//     Apollo / Warmly-Intent / Referral / Manual, so 'demo' cannot be entered at all. Note that
//     this disagrees with SHEET_SCHEMA.md, which documents the column as the PRODUCT config
//     ('oryoniq' / 'visioneerit'). The live sheet's meaning is "how did this lead arrive"; the
//     doc's is "which product owns it". Matching the sheet, since the sheet is what a human types
//     into — but the two need reconciling.
//
//     The loop guard still holds: the intake pipeline writes 'oryoniq'/'visioneerit', and Apollo-
//     sourced rows carry 'Apollo'. Neither matches 'manual', so this schedule cannot re-trigger on
//     rows the system itself appended.
//   channel_state_email blank — the claim marker. This polls every minute, so a row already picked
//                               up must never be picked up again. Leads has no `status` column;
//                               channel_state_email is the column that means exactly this
//                               (not_sent / queued / sent / bounced), so it is the honest one to use.
const rows = $input.all().map((i) => i.json || {});
const clean = (v, cap = 160) => (typeof v === 'string'
  ? v.replace(/[\u0000-\u001f\u007f]+/g, ' ').trim().slice(0, cap) : '');

// FIX 3 (2026-09-05) — 'manual' alone was starving the pipeline.
//
// This used to read `!== 'manual'`, which was two guards wearing one hat: "only send rows a human
// typed" AND "never re-trigger on rows the system appended". The second job now belongs entirely to
// channel_state_email (FIX 1 made that column reliable), and the first was blocking the path Apollo
// leads have to take. The first real Apollo pull — a verified, safe address for a genuine federal
// contractor — landed in Leads as not_sent and was skipped on every poll, silently and forever.
//
// So this is a WHITELIST, not a removal. Dropping the check entirely would mean any future source
// auto-sends the moment someone invents it, which is exactly the kind of implicit widening that
// puts mail in front of people nobody decided to contact. A new source has to be added here on
// purpose.
const SOURCES = new Set(['manual', 'apollo']);

const out = [];
for (const r of rows) {
  if (!SOURCES.has(clean(r.source_config).toLowerCase())) continue;
  // FIX 1 (2026-08-29) — the handoff column.
  //
  // This used to require `channel_state_email` to be BLANK. Nothing that writes a lead leaves it
  // blank: VIO-intake-verify-curate stamps 'not_sent' and VIO-inbox-mapper used to stamp
  // 'needs_review'. So every staff-typed lead landed in Leads, looked perfectly correct to a human
  // reading the sheet, and was never picked up. The two halves disagreed about one cell.
  //
  // READY is now an explicit list rather than the absence of a value. Blank still counts (a row
  // typed straight into Leads by hand), and 'not_sent' is what the verified intake path writes.
  // Everything else — queued, sent, pending_approval, replied, bounced, unsubscribed — means this
  // row is already somewhere in the pipeline and must not be restarted.
  // READY is an explicit list, never "this cell is empty".
  //   ''            a row typed straight into Leads by hand
  //   not_sent      verification passed and wrote it; ready to run
  //   approved      a HUMAN vouched for a lead verification would not pass on its own
  //
  // `approved` is the human override, added 2026-08-29, and it exists because of a real case:
  // visioneerit.com is a CATCH-ALL domain. It accepts mail for any address, so no verifier can
  // confirm that a specific mailbox exists there — Reoon returns is_deliverable:true but
  // is_safe_to_send:false, and intake correctly parks the lead at needs_review.
  //
  // Weakening the automatic rule to let catch-alls through would let unverified strangers into
  // the pipeline, which is exactly what verification is for. Instead a person who KNOWS the
  // mailbox exists sets the row to `approved` and takes responsibility for that one lead. The
  // Slack approval gate still stands after this — `approved` buys a lead the right to be drafted,
  // not the right to be sent.
  //
  // Everything else — queued, sent, pending_approval, replied, bounced, unsubscribed, dropped,
  // needs_review — means hands off.
  const READY = new Set(['', 'not_sent', 'approved']);
  const state = clean(r.channel_state_email).toLowerCase();
  if (!READY.has(state)) continue;

  const first_name = clean(r.first_name, 80);
  const company    = clean(r.company, 160);
  const email      = clean(r.contact_email, 160).toLowerCase();
  if (!first_name && !company && !email) continue;

  // FIX 3 (2026-08-29) — which product is this lead being pitched?
  //
  // `draft_config` was hardcoded 'oryoniq', so a council CIO typed in for VisioneerIT was drafted
  // GovCon capture copy signed OryonIQ. The product now comes from the sheet's `Product` column
  // (capital P — that is the live column name).
  //
  // An unknown or missing product REFUSES the row rather than guessing. A wrong guess sends the
  // wrong company's pitch to a real person, and that cannot be taken back; a refused row costs
  // somebody ten seconds with a dropdown. `source_config` is deliberately NOT consulted as a
  // fallback — on the live sheet it means how the lead ARRIVED (Apollo / Warmly-Intent / Referral
  // / Manual), which says nothing about which product owns it.
  const PRODUCTS = { oryoniq: 'oryoniq', visioneerit: 'visioneerit' };
  const productRaw = clean(r.Product ?? r.product, 40);
  const product = PRODUCTS[productRaw.toLowerCase().replace(/[^a-z]/g, '')] || '';

  const problems = [];
  if (!product) {
    problems.push(productRaw
      ? `'${productRaw}' is not a product — use OryonIQ or VisioneerIT`
      : 'Product is blank — choose OryonIQ or VisioneerIT');
  }
  if (!first_name) problems.push('first_name is blank');
  if (!company)    problems.push('company is blank');
  if (!/^[^\s@,;<>"]+@[^\s@,;<>"]+\.[^\s@,;<>"]+$/.test(email)) {
    problems.push(email ? `'${email}' is not a single valid address` : 'contact_email is blank');
  }

  out.push({ json: {
    row_number: r.row_number ?? null,
    first_name, company, email,
    // The REAL verification state, carried through so the enrolment step can decide for itself.
    // It used to be hardcoded 'pass' two nodes later, which would have told the ungated email path
    // that every lead was Reoon-verified — including the ones a human had to vouch for by hand.
    verify_action: clean(r.verify_action, 40),
    reoon_status: clean(r.reoon_status, 40),
    lead_state: state,
    title: clean(r.title, 120) || '(role)',
    company_domain: clean(r.company_domain, 160),
    // Was `product: 'demo'`, which pointed at a throwaway campaign carrying OryonIQ's copy. The
    // lead's own product is the only thing that decides now; 'demo' is gone from the send path.
    product,
    draft_config: product,
    invalid: problems.length > 0,
    problems: problems.join('; '),
  }});
}
// ⚠️ ONE LEAD PER CYCLE. This is a correctness constraint, not throttling.
//
// Four nodes downstream — Shape for page, Shape for enrolment, Claim row, Shape row update — read
// their lead with `$('Shape for drafting').first()`. In a multi-item run `.first()` is ALWAYS item
// zero, so with two leads in one cycle the second one is built from the FIRST one's identity.
// Proven by running the real node code: processing "Bob" produced Alice's company, Alice's address
// and no product at all. That is a personalized page branded with the wrong company, and an
// enrolment aimed at the wrong person.
//
// It has never fired only because exactly one lead has been ready per cycle so far. At 15-20 sends
// a day, with staff pasting lists, that stops being true immediately.
//
// Capping here fixes every one of those four call sites at once and cannot be partially applied.
// The alternative — correlating each node to its own item — is four separate edits where getting
// any single one wrong reintroduces the same silent mix-up. At a 3-minute poll this still clears
// 20 leads an hour, comfortably above the daily target.
//
// If throughput ever needs to rise, raise it by SHORTENING THE POLL, never by lifting this cap,
// unless all four nodes have been re-verified against a genuine multi-item batch.
if (out.length > 1) {
  const first = out[0];
  first.batch_note = `${out.length} leads were ready; taking one this cycle, the rest follow on the next polls`;
  return [{ json: first.json ? first.json : first }].map((x) => (x.json ? x : { json: x }));
}
return out;

const r = $input.item.json;
return { json: { row_number: r.row_number, channel_state_email: 'needs_review',
                 verify_reason: `demo row not processed — ${r.problems}`,
                 updated_at: new Date().toISOString() } };

const r = $input.item.json;
return { json: { first_name: r.first_name, title: r.title, company: r.company,
                 source_config: r.draft_config,
                 _row: r.row_number, _email: r.email, _company: r.company,
                 _first_name: r.first_name, _title: r.title, _domain: r.company_domain,
                 _verify_action: r.verify_action, _reoon_status: r.reoon_status,
                 _lead_state: r.lead_state } };

// Shape for VIO-sendr-generate-page.
//
// The identity fields (_row, _email, ...) are read back from 'Shape for drafting', NOT from the
// item in front of us. An Execute Workflow call returns only what the SUB-workflow's own output
// node emits — anything the caller attached to the input is gone. Carrying them on the input and
// expecting them back produced an enrolment with a blank address and "(unnamed lead)", which the
// gate correctly refused. Each execution here handles one row (mode: 'each'), so first() is that
// row's context.
const drafted = $input.item.json;
const src = $('Shape for drafting').first().json;
return { json: {
  // FIX 3 (2026-08-29): was hardcoded 'oryoniq'. The row's own product, carried through
  // 'Shape for drafting' as source_config, decides which template and campaign copy is used.
  product: src.source_config,
  // ⚠️ THE SUB-WORKFLOW READS THESE NAMES, NOT THE UNDERSCORE ONES.
  // VIO-sendr-generate-page's 'Build Page Request' reads lead.opener, lead.contact_email and
  // lead.title. Only `_opener` / `_email` / `_title` were being sent, so every personalized page
  // has been rendering the TEMPLATE'S PLACEHOLDER opener instead of the line OpenAI wrote for that
  // lead, with no address attached. The underscore copies stay because this workflow's own later
  // nodes read them.
  opener: src._opener || '',
  contact_email: src._email || '',
  first_name: src._first_name, title: src._title,
  company: src._company, company_domain: src._domain || '',
  _row: src._row, _email: src._email, _first_name: src._first_name,
  _title: src._title, _company: src._company,
  _opener: typeof drafted.opener === 'string' ? drafted.opener.trim() : '',
  _email_draft: typeof drafted.email === 'string' ? drafted.email : '',
  _product: drafted.config_used || drafted.product || src.source_config || '',
  _signal: typeof drafted.signal === 'string' ? drafted.signal : '',
  _verify_action: src._verify_action || '', _reoon_status: src._reoon_status || '',
  _lead_state: src._lead_state || '',
} };

// Hand the EMAIL enrolment path one lead.
//
// ⚠️ THIS PATH HAS NO SLACK APPROVAL, ON PURPOSE (2026-08-30, owner's instruction). The target is
// 15-20 outreach a day and a click per lead does not scale. What makes that defensible is that a
// HUMAN CHOSE EVERY RECIPIENT by typing them into the Inbox tab — no model picks who gets mailed
// on this path. VIO-enrol-email replaces the click with five checks that throw: verified-or-vouched,
// suppression re-read at send time, product must resolve to a real campaign, the AI-written opener
// is sanity-checked, and a hard daily cap counted from what actually sent.
//
// The gate REMAINS on VIO-agent-tool-push-instantly, which is the autonomous agent's tool and the
// one place an LLM chooses recipients. If leads ever start reaching THIS path from an automated
// source, the gate has to come back with them.
//
// ⚠️ THE PAGE URL MUST BE READ FROM 'Generate Sendr page' BY NAME.
//
// Not from the item in front of this node. The chain is
//     Generate Sendr page -> Claim row (pending_approval) -> Claim row in sheet -> Shape for enrolment
// and 'Claim row in sheet' is a Sheets UPDATE whose output is the ROW IT WROTE, not the page
// result. Anything reading $input for pageUrl past that point gets the sheet row and finds
// nothing. Found live 2026-08-29: Sendr really did build the page
// (https://sendrpage.com/... , page id returned, no warnings) and the enrolment gate still
// refused with "no sendr_page_url", because the URL had been overwritten one node earlier.
// The claim step was inserted between them later, which silently invalidated both readers.

const page = $('Generate Sendr page').first().json.pageUrl || '';
const src = $('Shape for page').first().json;
if (!src._email) {
  throw new Error(`REFUSED: row ${src._row} lost its contact_email between stages — refusing to propose an enrolment the human could not act on.`);
}
// Fail loudly rather than proposing an enrolment the campaign cannot render: step 1's CTA is the
// {{sendrPageUrl}} merge tag, so an empty page URL ships a broken sentence to a real prospect.
if (!page) {
  throw new Error(`REFUSED: row ${src._row} reached enrolment with no Sendr page URL — the campaign CTA is {{sendrPageUrl}} and would render empty.`);
}
// ⚠️ THE PRODUCT MUST BE THE LEAD'S OWN, NOT A CONSTANT.
// This said `product: 'demo'`. push-instantly maps that key to the demo campaign, which carries
// OryonIQ's step-1 body verbatim — so an approved VisioneerIT lead was going to be sent OryonIQ's
// copy while linking to a VisioneerIT Sendr page, and it also walked straight past that tool's
// deliberate fail-closed `visioneerit: null` refusal. Cross-product copy leaking between the two
// products is a mistake this build has already made once and it is the one a prospect sees.
// Now the lead's real product decides, and an unsupported one is refused before a human is asked.
const product = String(src._product || '').toLowerCase().replace(/[^a-z]/g, '');
if (!product) {
  throw new Error(`REFUSED: row ${src._row} reached enrolment with no product — refusing to guess which company is pitching this person.`);
}
return { json: {
  product,
  allow_recontact: true,
  leads: [{
    first_name: src._first_name, title: src._title, company: src._company,
    contact_email: src._email, sendr_page_url: page,
    opener: src._opener,
    // ⚠️ NOT hardcoded 'pass' any more. VIO-enrol-email decides for itself whether an address may
    // be mailed, and telling it every lead was verified would have made that check meaningless —
    // including for catch-all addresses that only got through because a human vouched by name.
    verify_action: src._verify_action || '',
    reoon_status: src._reoon_status || '',
    channel_state_email: src._lead_state || '',
  }],
  _row: src._row, _page: page, _opener: src._opener, _email_draft: src._email_draft,
  _product: src._product, _signal: src._signal,
} };

// Write the outcome back onto the row the human is watching. Uses Leads' own columns — there is
// no invented schema here.
const scrub = (v) => (typeof v === 'string' ? v.replace(/[\u0000-\u001f\u007f]+/g, ' ') : v);
const src = $('Shape for enrolment').first().json;
const r = $input.item.json;
// ⚠️ READ THE SHAPE THE CURRENT TARGET ACTUALLY EMITS.
//
// This read `r.leads[].status`, which is VIO-agent-tool-push-instantly's shape. The enrolment call
// was repointed to VIO-enrol-email on 2026-08-30 and that workflow emits a FLAT item with an
// `enrolled` boolean and no `leads` key at all — so this silently evaluated false on every
// successful send and wrote the lead back as needs_review.
//
// That is not a cosmetic mislabel: a lead that looks unsent can be vouched for again and mailed a
// SECOND time. Which is why an unrecognised shape now throws instead of defaulting to false —
// defaulting to false is precisely what hid this. A throw strands the row at pending_approval,
// which the operator can free deliberately; a wrong 'needs_review' invites a duplicate send that
// reaches a real person.
let enrolled;
if (typeof r.enrolled === 'boolean') {
  enrolled = r.enrolled;                                   // VIO-enrol-email
} else if (Array.isArray(r.leads)) {
  enrolled = r.leads.some((l) => l && l.status === 'enrolled');  // legacy gated tool
} else {
  throw new Error(`REFUSED: the enrolment step returned a shape this node does not recognise (keys: ${Object.keys(r || {}).join(', ') || 'none'}). Refusing to guess whether ${src._email || 'this lead'} was sent — guessing wrong either loses the record or mails them twice.`);
}
return { json: {
  row_number: src._row,
  // The sheet's own dropdown vocabulary — not the docs'. `not_sent` and `queued` are not valid
  // values in the live column; writing them through the API bypassed data validation and put
  // off-vocabulary strings in a column a human reads and filters on.
  //   enrolled  — the lead is on the campaign and will be mailed when it runs
  //   needs_review — the run completed but nothing landed (the address was already in another
  //                    campaign, say). NOT 'dropped'.
  //
  // ⚠️ 'dropped' is VERIFICATION's word for "Reoon says this address is not real", and
  // VIO-enrol-email now refuses a dropped address outright as a verified negative that no human
  // may override. Writing it here for "enrolment did not land" collided with that meaning and
  // permanently locked a perfectly good lead out of the pipeline — seen live 2026-08-30 on
  // gavriel.legynd@visioneerit.com, whose address was fine. Two writers, one column, two
  // vocabularies is the same bug class as the needs_review/blank handoff.
  channel_state_email: enrolled ? 'enrolled' : 'needs_review',
  opener: scrub(src._opener || ''),
  email_draft: scrub(src._email_draft || ''),
  sendr_page_url: src._page || '',
  // Which product pitched this person, and the claim they were told. source_config cannot carry
  // this: the live sheet repurposed that column to mean HOW the lead arrived (Apollo / Referral /
  // Manual), which is a different question from WHO pitched them.
  Product: src._product || '',
  signal: src._signal || '',
  updated_at: new Date().toISOString(),
} };

// ⚠️ THE PAGE URL MUST BE READ FROM 'Generate Sendr page' BY NAME.
//
// Not from the item in front of this node. The chain is
//     Generate Sendr page -> Claim row (pending_approval) -> Claim row in sheet -> Shape for enrolment
// and 'Claim row in sheet' is a Sheets UPDATE whose output is the ROW IT WROTE, not the page
// result. Anything reading $input for pageUrl past that point gets the sheet row and finds
// nothing. Found live 2026-08-29: Sendr really did build the page
// (https://sendrpage.com/... , page id returned, no warnings) and the enrolment gate still
// refused with "no sendr_page_url", because the URL had been overwritten one node earlier.
// The claim step was inserted between them later, which silently invalidated both readers.
//
// This node also wrote `src._page_pending`, a field 'Shape for page' has never produced — so the
// sheet's sendr_page_url column was being filled with an empty string on every run.
const src = $('Shape for page').first().json;
const page = $('Generate Sendr page').first().json.pageUrl || '';
return { json: {
  row_number: src._row,
  channel_state_email: 'pending_approval',
  opener: src._opener || '',
  email_draft: src._email_draft || '',
  sendr_page_url: page,
  Product: src._product || '',
  signal: src._signal || '',
  updated_at: new Date().toISOString(),
} };

// CLAIM FIRST, WORK SECOND.
//
// The row used to be claimed only after drafting AND page generation — roughly half a minute of
// OpenAI and Sendr calls — while the schedule re-read the same tab every 60 seconds. So the next
// cycle could read a row that was already being worked on, and propose it to a human twice. Seen
// live 2026-08-29: one row produced two Slack approval requests, two drafts and two Sendr pages.
//
// This node runs on a PARALLEL branch off 'Row usable?', not inline. That is deliberate: n8n's v1
// execution order runs the first connected branch to completion before the second, so the claim
// lands before drafting starts — while 'Shape for drafting' still receives the picked row itself.
// Putting the claim inline would hand the drafting chain a Google Sheets node's output instead,
// which is precisely the bug that cost the Sendr page URL earlier today.
//
// Only the state is written here. Everything else the row eventually carries (opener, draft, page
// URL) does not exist yet, and writing blanks for them would erase a previous run's values.
const r = $input.item.json;
return { json: {
  row_number: r.row_number,
  channel_state_email: 'pending_approval',
  updated_at: new Date().toISOString(),
} };

// HEARTBEAT — so a human can tell "working, nothing to do" from "dead".
//
// Staff type into this spreadsheet and nothing on screen tells them the poller is alive. Both
// scheduled workflows are silent by design when there is nothing to pick up: the mapper's chain
// literally stops at the sheet read when no row is claimable, so an idle system and a broken one
// look identical from the sheet. This writes one row per workflow into the `System` tab on EVERY
// cycle, whether or not it found work.
//
// It hangs off the sheet READ rather than the schedule trigger, so it reports what was actually
// seen, not merely that a timer fired. It is a parallel branch and the first one connected, so it
// records the check even if the work that follows throws.
const EVERY_MIN = 3;
const raw = $input.all().map((i) => i.json || {});
// A failed sheet read arrives as a single item carrying an error. Report that plainly instead of
// counting it as a lead — "could not read the sheet" is the single most useful thing this row can
// say, and it used to say nothing at all because the failure stopped the chain before this node.
const readFailed = raw.length === 1 && raw[0] && typeof raw[0].error !== 'undefined';
const rows = readFailed ? [] : raw;
const real = rows.filter((r) => Object.keys(r).some((k) => k !== 'row_number' && String(r[k] ?? '').trim()));
// Must use the SAME source rule as `Pick demo rows`, or the liveness board tells staff a number
// the sender does not act on — "3 waiting" that never move is worse than no number at all.
const WAITING_SOURCES = new Set(['manual', 'apollo']);
const waiting = real.filter((r) => ['', 'not_sent', 'approved'].includes(String(r.channel_state_email ?? '').trim().toLowerCase()) && WAITING_SOURCES.has(String(r.source_config ?? '').trim().toLowerCase())).length;
const now = new Date();
const next = new Date(now.getTime() + EVERY_MIN * 60000);
// Local time, not UTC. This row exists to be glanced at by staff mid-typing — "17:48" is a thing
// a person can compare to the clock on their wall; "21:48 UTC" needs arithmetic first, which is
// exactly the friction that makes a status row go unread.
const TZ = 'America/Detroit';
const local = (d) => d.toLocaleString('en-US', { timeZone: TZ, hour12: true,
  month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
const hhmm = (d) => d.toLocaleString('en-US', { timeZone: TZ, hour12: true, hour: 'numeric', minute: '2-digit' });
return { json: {
  workflow: "VIO-run-outreach (sends the email)",
  last_run_at: local(now),
  checked: `${real.length} lead(s) in Leads`,
  waiting: waiting,
  last_result: readFailed
    ? 'COULD NOT READ THE SHEET — Google rate-limited us. It retries on the next cycle; no lead is lost.'
    : (waiting ? `${waiting} lead(s) ready to run` : 'no leads ready'),
  every: `${EVERY_MIN} min`,
  next_check_at: hhmm(next),
} };
